import os
from pathlib import Path
from dotenv import load_dotenv

# Locate directories
BASE_DIR = Path(__file__).resolve().parent.parent
ROOT_DIR = BASE_DIR.parent

# Load variables: priority to root .env.local (generated by neon deploy), then backend .env
if (ROOT_DIR / ".env.local").exists():
    load_dotenv(dotenv_path=ROOT_DIR / ".env.local")
if (BASE_DIR / ".env.local").exists():
    load_dotenv(dotenv_path=BASE_DIR / ".env.local")
if (BASE_DIR / ".env").exists():
    load_dotenv(dotenv_path=BASE_DIR / ".env")

# Database settings
DATABASE_URL = os.getenv(
    "DATABASE_URL",
    "postgresql+psycopg2://postgres:postgres@localhost:5432/insightiq",
)

# Normalize postgresql:// to postgresql+psycopg2:// for SQLAlchemy compatibility with psycopg2
if DATABASE_URL.startswith("postgresql://"):
    DATABASE_URL = DATABASE_URL.replace("postgresql://", "postgresql+psycopg2://", 1)

# Groq settings
GROQ_API_KEY = os.getenv("GROQ_API_KEY", "")
GROQ_MODEL = os.getenv("GROQ_MODEL", "llama-3.3-70b-versatile")

# CORS allowed frontend origins
CORS_ORIGINS = [
    "http://localhost:5173",
    "http://127.0.0.1:5173",
]
